ALTER TABLE "classroom_draft_media_tasks" ADD CONSTRAINT "classroom_draft_media_tasks_source_check" CHECK (("classroom_draft_media_tasks"."kind" = 'audio' AND "classroom_draft_media_tasks"."action_id" IS NOT NULL AND "classroom_draft_media_tasks"."element_id" IS NULL) OR ("classroom_draft_media_tasks"."kind" IN ('image', 'video') AND "classroom_draft_media_tasks"."action_id" IS NULL AND "classroom_draft_media_tasks"."element_id" IS NOT NULL));